  `description` VARCHAR(255) NULL DEFAULT NULL COMMENT 'รายละเอียด/เงื่อนไขเพิ่มเติมของกิจกรรม',
  `status` ENUM('ACTIVE', 'INACTIVE') NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE=เปิดให้ส่งกิจกรรมนี้ได้, INACTIVE=ปิดรับชั่วคราว (เช่น ปรับคะแนนใหม่)',
