DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'ข้อมูล login สำหรับหน้าแอดมิน แยกจากช่องทาง LINE login ของพนักงานทั่วไป';


-- -----------------------------------------------------
-- Table `wellness_db`.`assessment_campaign`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `wellness_db`.`assessment_campaign` (
  `campaign_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัสรอบ follow-up (PK)',
  `campaign_name` VARCHAR(100) NOT NULL COMMENT 'ชื่อรอบ เช่น \"ติดตามผล 8 สัปดาห์ รอบที่ 1\"',
  `release_date` DATE NOT NULL COMMENT 'วันที่พนักงานเริ่มเห็นแบบสอบถามนี้ใน LIFF',
  `close_date` DATE NULL DEFAULT NULL COMMENT 'วันที่ปิดรับ (ถ้ากำหนดไว้) — ไม่บังคับ ปิดเองผ่านปุ่ม admin ก็ได้โดยไม่ต้องตั้งวันที่',
  `included_fields` JSON NOT NULL COMMENT 'รายชื่อ field (camelCase ตรงกับ payload ของ HealthAssessmentWizard) ที่รอบนี้จะถาม เช่น [\"weightKg\",\"waistCm\",\"vigorousDays\",\"vigorousMinutes\"]',
  `status` ENUM('DRAFT', 'OPEN', 'CLOSED') NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT=ยังไม่เปิด, OPEN=พนักงานเห็น/ตอบได้, CLOSED=ปิดรับแล้ว',
  `created_by` VARCHAR(20) NULL DEFAULT NULL COMMENT 'employee_id ของแอดมินที่สร้างรอบนี้ (FK -> admin_credential.employee_id)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`campaign_id`))
ENGINE = InnoDB
AUTO_INCREMENT = 6
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'รอบแบบสอบถามติดตามผล (follow-up) ที่ admin เปิดให้พนักงานกรอกเพิ่มหลัง baseline — เลือกได้ว่าจะถามฟิลด์ไหนบ้าง';


