CREATE TABLE IF NOT EXISTS `wellness_db`.`badge` (
  `badge_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัส Badge (PK)',
  `badge_name` VARCHAR(100) NOT NULL COMMENT 'ชื่อ Badge เช่น \"Runner\", \"Marathon Master\"',
  `description` VARCHAR(255) NULL DEFAULT NULL COMMENT 'คำอธิบาย Badge / เงื่อนไขการได้รับแบบอ่านง่าย',
