  `condition_type` VARCHAR(50) NOT NULL COMMENT 'ประเภทเงื่อนไข เช่น DISTANCE (ระยะทางสะสม), SUBMISSION_COUNT (จำนวนครั้งที่ส่ง), SCORE (คะแนนสะสม)',
  `condition_value` INT NOT NULL COMMENT 'ค่าที่ต้องทำถึงจึงจะได้ Badge เช่น 100 (กม.)',
  `status` ENUM('ACTIVE', 'INACTIVE') NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE=เปิดให้ระบบตรวจและแจกได้, INACTIVE=ปิด ไม่แจกเพิ่ม (ของเดิมที่แจกไปแล้วไม่หาย)',
  PRIMARY KEY (`badge_id`))
ENGINE = InnoDB
AUTO_INCREMENT = 9
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'เหรียญตราความสำเร็จที่พนักงานสะสมได้';


