CREATE TABLE IF NOT EXISTS `wellness_db`.`challenge` (
  `challenge_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัส Challenge (PK)',
  `category_id` INT NOT NULL COMMENT 'หมวดหมู่กิจกรรมที่ใช้วัดใน challenge นี้ (FK -> activity_category.category_id)',
