  `start_date` DATETIME NOT NULL COMMENT 'วันเวลาเริ่ม Challenge',
  `end_date` DATETIME NOT NULL COMMENT 'วันเวลาสิ้นสุด Challenge',
  `status` ENUM('UPCOMING', 'ONGOING', 'ENDED', 'CANCELLED') NOT NULL DEFAULT 'UPCOMING' COMMENT 'UPCOMING=ยังไม่เริ่ม, ONGOING=กำลังแข่งขัน, ENDED=จบแล้ว, CANCELLED=ถูกยกเลิกโดย admin',
