CREATE TABLE IF NOT EXISTS `wellness_db`.`running_submission` (
  `submission_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัสการส่ง (PK)',
  `employee_id` VARCHAR(20) NOT NULL COMMENT 'รหัสพนักงานผู้ส่งกิจกรรม',
  `activity_id` INT NOT NULL COMMENT 'ประเภทกิจกรรมที่ส่ง',
