  `approved_by` VARCHAR(20) NULL DEFAULT NULL COMMENT 'รหัส admin ผู้ตรวจสอบ/อนุมัติ',
  `approved_at` DATETIME NULL DEFAULT NULL COMMENT 'วันเวลาที่อนุมัติ/ปฏิเสธ',
  `submitted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่พนักงานส่งกิจกรรม',
  PRIMARY KEY (`submission_id`),
  INDEX `fk_running_submission_activity_type_idx` (`activity_id` ASC) VISIBLE,
  INDEX `idx_running_submission_employee` (`employee_id` ASC) VISIBLE,
  INDEX `fk_running_submission_reject_reason` (`reject_reason_id` ASC) VISIBLE,
