    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_running_submission_reject_reason`
    FOREIGN KEY (`reject_reason_id`)
    REFERENCES `wellness_db`.`reject_reason` (`reason_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE)
ENGINE = InnoDB
AUTO_INCREMENT = 25
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'ประวัติการส่งผลกิจกรรมของพนักงานแต่ละครั้ง';


