-- -----------------------------------------------------
-- Table `wellness_db`.`employee_account`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `wellness_db`.`employee_account` (
  `account_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัสบัญชี (PK)',
  `employee_id` VARCHAR(20) NOT NULL COMMENT 'รหัสพนักงาน (placeholder รอเชื่อมระบบ Pulse/HR)',
  `provider` ENUM('LINE') NOT NULL DEFAULT 'LINE' COMMENT 'ผู้ให้บริการ login ปัจจุบันมีแค่ LINE',
  `provider_user_id` VARCHAR(255) NOT NULL COMMENT 'LINE User ID (userId ที่ได้จาก LINE Login/Messaging API)',
  `display_name` VARCHAR(100) NULL DEFAULT NULL COMMENT 'ชื่อที่แสดงจาก LINE profile',
  `picture_url` VARCHAR(255) NULL DEFAULT NULL COMMENT 'URL รูปโปรไฟล์จาก LINE',
  `linked_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่เชื่อมบัญชีครั้งแรก',
  `last_login` DATETIME NULL DEFAULT NULL COMMENT 'วันเวลาเข้าใช้งานล่าสุด',
  `status` ENUM('ACTIVE', 'INACTIVE', 'REVOKED') NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE=ใช้งานได้ปกติ, INACTIVE=ไม่ได้ใช้งาน/ยังไม่ยืนยัน, REVOKED=ถูกตัดสิทธิ์ (เช่น พนักงานลาออก)',
  PRIMARY KEY (`account_id`),
  UNIQUE INDEX `uq_provider_user` (`provider` ASC, `provider_user_id` ASC) COMMENT '\'กัน LINE user คนเดียวกัน login แล้วสร้างบัญชีซ้ำ\'' VISIBLE,
  INDEX `idx_employee_account_employee` (`employee_id` ASC) VISIBLE,
  INDEX `fk_employee_account_employee_idx` (`employee_id` ASC) VISIBLE,
  CONSTRAINT `fk_employee_account_employee`
    FOREIGN KEY (`employee_id`)
    REFERENCES `wellness_db`.`employee` (`employee_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE)
ENGINE = InnoDB
AUTO_INCREMENT = 4
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'การเชื่อมบัญชีพนักงานกับ LINE OA';


-- -----------------------------------------------------
-- Table `wellness_db`.`employee_badge`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `wellness_db`.`employee_badge` (
  `employee_badge_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัส (PK)',
  `employee_id` VARCHAR(20) NOT NULL COMMENT 'รหัสพนักงานผู้ได้รับ Badge',
  `badge_id` INT NOT NULL COMMENT 'Badge ที่ได้รับ (FK -> badge.badge_id)',
  `received_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่ได้รับ Badge (ระบบคำนวณเงื่อนไขผ่านแล้ว)',
  PRIMARY KEY (`employee_badge_id`),
  UNIQUE INDEX `uq_employee_badge` (`employee_id` ASC, `badge_id` ASC) COMMENT '\'กันพนักงานได้ Badge เดิมซ้ำสองครั้ง\'' VISIBLE,
  INDEX `fk_employee_badge_badge_idx` (`badge_id` ASC) VISIBLE,
  CONSTRAINT `fk_employee_badge_badge`
    FOREIGN KEY (`badge_id`)
    REFERENCES `wellness_db`.`badge` (`badge_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_employee_badge_employee`
    FOREIGN KEY (`employee_id`)
    REFERENCES `wellness_db`.`employee` (`employee_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE)
ENGINE = InnoDB
AUTO_INCREMENT = 6
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'บันทึก Badge ที่พนักงานแต่ละคนสะสมได้แล้ว';


-- -----------------------------------------------------
-- Table `wellness_db`.`health_assessment`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `wellness_db`.`health_assessment` (
  `assessment_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัสแบบประเมิน (PK)',
  `employee_id` VARCHAR(20) NOT NULL COMMENT 'พนักงานเจ้าของแบบประเมินนี้ (FK -> employee.employee_id) — 1 คนมีได้ 1 แถว (baseline ครั้งเดียว)',
  `assessment_type` ENUM('BASELINE', 'FOLLOWUP') NOT NULL DEFAULT 'BASELINE' COMMENT 'BASELINE = ครั้งแรกตอน onboarding, FOLLOWUP = รอบติดตามผล',
  `campaign_id` INT NULL DEFAULT NULL COMMENT 'อ้างอิงรอบ follow-up จาก assessment_campaign — NULL สำหรับแถว BASELINE',
  `consent_accepted_at` DATETIME NULL DEFAULT NULL COMMENT 'วันเวลาที่ยินยอมตาม PDPA — บันทึกครั้งเดียวตอน BASELINE เท่านั้น แถว FOLLOWUP จะเป็น NULL (ไม่ถามซ้ำ)',
  `weight_kg` DECIMAL(4,1) NULL DEFAULT NULL,
  `height_cm` DECIMAL(5,1) NULL DEFAULT NULL,
  `bmi` DECIMAL(4,1) GENERATED ALWAYS AS ((`weight_kg` / pow((`height_cm` / 100),2))) STORED COMMENT 'ดัชนีมวลกาย คำนวณอัตโนมัติจาก weight_kg/height_cm² (ข้อ 2.3) — generated column ห้าม insert ตรง',
  `waist_cm` DECIMAL(4,1) NULL DEFAULT NULL COMMENT 'รอบเอว หน่วยเซนติเมตร ทศนิยม 1 ตำแหน่ง (ข้อ 2.4)',
  `bp_systolic` INT NULL DEFAULT NULL COMMENT 'ความดันโลหิตล่าสุดที่ทราบ ค่าบน (ข้อ 2.5) — ไม่บังคับกรอกถ้าไม่ทราบ',
  `bp_diastolic` INT NULL DEFAULT NULL COMMENT 'ความดันโลหิตล่าสุดที่ทราบ ค่าล่าง (ข้อ 2.5) — ไม่บังคับกรอกถ้าไม่ทราบ',
  `assessment_date` DATE NULL DEFAULT NULL,
  `chronic_disease` JSON NULL DEFAULT NULL COMMENT 'โรคประจำตัว เลือกได้มากกว่า 1 ข้อ (ข้อ 3.1) เช่น [\"เบาหวาน\",\"ความดันโลหิตสูง\"] — NULL/[] = ไม่มี',
  `chronic_disease_other` VARCHAR(255) NULL DEFAULT NULL COMMENT 'ระบุโรคประจำตัวอื่นๆ เพิ่มเติมนอกเหนือจาก preset ในข้อ 3.1',
  `smoking_status` ENUM('NONE', 'SMOKER', 'FORMER') NOT NULL DEFAULT 'NONE' COMMENT 'พฤติกรรมสูบบุหรี่ (ข้อ 3.2): NONE=ไม่สูบ, SMOKER=สูบ, FORMER=เลิกแล้ว',
  `alcohol_status` ENUM('NONE', 'OCCASIONAL', 'REGULAR') NOT NULL DEFAULT 'NONE' COMMENT 'พฤติกรรมดื่มแอลกอฮอล์ (ข้อ 3.3): NONE=ไม่ดื่ม, OCCASIONAL=ครั้งคราว, REGULAR=เป็นประจำ',
  `physical_limitation` TINYINT(1) NOT NULL DEFAULT '0' COMMENT 'มีข้อจำกัดทางร่างกายที่มีผลต่อการออกกำลังกายหรือไม่ (ข้อ 3.4): 0=ไม่มี, 1=มี',
  `physical_limitation_note` VARCHAR(255) NULL DEFAULT NULL COMMENT 'รายละเอียดข้อจำกัดทางร่างกาย ถ้า physical_limitation = 1',
  `vigorous_days` TINYINT NOT NULL DEFAULT '0' COMMENT 'จำนวนวัน/สัปดาห์ที่ออกกำลังกายระดับหนัก 0-7 วัน (ข้อ 4.1)',
  `vigorous_minutes` INT NULL DEFAULT NULL COMMENT 'เวลาเฉลี่ยต่อครั้งที่ออกกำลังกายระดับหนัก หน่วยนาที (ข้อ 4.2)',
  `moderate_days` TINYINT NOT NULL DEFAULT '0' COMMENT 'จำนวนวัน/สัปดาห์ที่ออกกำลังกายระดับปานกลาง 0-7 วัน (ข้อ 4.3)',
  `moderate_minutes` INT NULL DEFAULT NULL COMMENT 'เวลาเฉลี่ยต่อครั้งที่ออกกำลังกายระดับปานกลาง หน่วยนาที (ข้อ 4.4)',
  `walking_days` TINYINT NOT NULL DEFAULT '0' COMMENT 'จำนวนวัน/สัปดาห์ที่เดินเพื่อออกกำลังกาย/สันทนาการ 0-7 วัน (ข้อ 4.5)',
  `walking_minutes` INT NULL DEFAULT NULL COMMENT 'เวลาเฉลี่ยต่อครั้งที่เดินเพื่อออกกำลังกาย/สันทนาการ หน่วยนาที (คู่กับ walking_days ข้อ 4.5)',
  `exercise_pattern` JSON NULL DEFAULT NULL COMMENT 'รูปแบบการออกกำลังกายที่ทำเป็นประจำ เลือกได้มากกว่า 1 (ข้อ 4.6) เช่น [\"เดิน/วิ่ง\",\"โยคะ\"]',
  `exercise_barrier` VARCHAR(50) NULL DEFAULT NULL COMMENT 'อุปสรรคสำคัญที่สุดที่ทำให้ออกกำลังกายไม่สม่ำเสมอ (ข้อ 4.7): ไม่มีเวลา/เหนื่อยล้าจากงาน/ไม่มีสถานที่-อุปกรณ์/ไม่มีแรงจูงใจ/เข้าเวรไม่แน่นอน/อื่นๆ',
  `met_minutes_per_week` DECIMAL(7,1) GENERATED ALWAYS AS (((((8.0 * coalesce(`vigorous_days`,0)) * coalesce(`vigorous_minutes`,0)) + ((4.0 * coalesce(`moderate_days`,0)) * coalesce(`moderate_minutes`,0))) + ((3.3 * coalesce(`walking_days`,0)) * coalesce(`walking_minutes`,0)))) STORED COMMENT 'MET-minutes/week ตาม IPAQ scoring (METs: หนัก=8.0, ปานกลาง=4.0, เดิน=3.3) คำนวณอัตโนมัติ ห้าม insert ตรง — ฟิลด์ที่ใช้คำนวณถ้าเป็น NULL (เช่น follow-up ไม่ได้ถามข้อนั้น) จะนับเป็น 0 ในสูตรนี้ ไม่ทำให้ทั้งค่าเป็น NULL',
  `meals_per_day` ENUM('1', '2', '3', 'MORE_THAN_3') NULL DEFAULT NULL,
  `fried_food_freq` ENUM('NEVER', '1_2_PER_WEEK', '3_4_PER_WEEK', '5_PLUS_PER_WEEK') NULL DEFAULT NULL,
  `sweet_food_freq` ENUM('NEVER', '1_2_PER_WEEK', '3_4_PER_WEEK', '5_PLUS_PER_WEEK') NULL DEFAULT NULL,
  `veggie_fruit_freq` ENUM('NONE', '1_SERVING', '2_SERVINGS', '3_PLUS_SERVINGS') NULL DEFAULT NULL,
  `late_night_eating` ENUM('NEVER', 'SOMETIMES', 'REGULARLY') NULL DEFAULT NULL,
  `past_dieting` ENUM('NEVER', 'CURRENTLY', 'PAST_ONLY') NULL DEFAULT NULL,
  `goal_type` JSON NULL DEFAULT NULL,
  `stage_of_change` ENUM('NOT_CONSIDERING', 'CONSIDERING_6M', 'PLANNING_1M', 'ACTIVE_UNDER_6M', 'ACTIVE_OVER_6M') NULL DEFAULT NULL,
  `target_weight_kg` DECIMAL(4,1) NULL DEFAULT NULL COMMENT 'น้ำหนักเป้าหมายที่ต้องการ ถ้ามี หน่วยกิโลกรัม (ข้อ 6.3)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่บันทึกแถวนี้ลงระบบ',
  PRIMARY KEY (`assessment_id`),
  INDEX `fk_health_assessment_campaign` (`campaign_id` ASC) VISIBLE,
  INDEX `idx_health_assessment_employee_campaign` (`employee_id` ASC, `campaign_id` ASC) VISIBLE,
  CONSTRAINT `fk_health_assessment_campaign`
    FOREIGN KEY (`campaign_id`)
    REFERENCES `wellness_db`.`assessment_campaign` (`campaign_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_health_assessment_employee`
    FOREIGN KEY (`employee_id`)
    REFERENCES `wellness_db`.`employee` (`employee_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE)
ENGINE = InnoDB
AUTO_INCREMENT = 6
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'แบบสอบถามข้อมูลสุขภาพพื้นฐานและพฤติกรรมออกกำลังกาย (baseline) กรอกครั้งเดียวตอน onboarding — ยังไม่รองรับ follow-up/campaign';


-- -----------------------------------------------------
-- Table `wellness_db`.`reward`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `wellness_db`.`reward` (
  `reward_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัสของรางวัล (PK)',
  `reward_name` VARCHAR(150) NOT NULL COMMENT 'ชื่อของรางวัล เช่น \"กระบอกน้ำ\"',
  `required_score` INT NOT NULL COMMENT 'คะแนนที่ต้องใช้แลก 1 ชิ้น',
  `stock` INT NOT NULL DEFAULT '0' COMMENT 'จำนวนคงเหลือ — ถูกหักทันทีตอน reward_redeem.status = PENDING (จองของ) และคืนกลับถ้า CANCELLED/REJECTED ภายหลัง เพื่อป้องกัน race condition ตอนของเหลือน้อย',
  `image` VARCHAR(255) NULL DEFAULT NULL COMMENT 'path/URL รูปของรางวัล',
  `description` VARCHAR(255) NULL DEFAULT NULL COMMENT 'รายละเอียดของรางวัล',
  `status` ENUM('ACTIVE', 'INACTIVE') NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE=เปิดให้แลกได้, INACTIVE=ปิดรับแลกชั่วคราว (ไม่ลบเพราะมีประวัติการแลกเก่าผูกอยู่)',
  PRIMARY KEY (`reward_id`))
ENGINE = InnoDB
AUTO_INCREMENT = 7
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'ของรางวัลที่แลกได้ด้วยคะแนนสะสม';


-- -----------------------------------------------------
-- Table `wellness_db`.`reward_redeem`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `wellness_db`.`reward_redeem` (
  `redeem_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัสการแลก (PK)',
  `employee_id` VARCHAR(20) NOT NULL COMMENT 'รหัสพนักงานผู้แลก',
  `reward_id` INT NOT NULL COMMENT 'ของรางวัลที่แลก (FK -> reward.reward_id)',
  `used_score` INT NOT NULL COMMENT 'คะแนนที่ถูกหักไปสำหรับการแลกครั้งนี้ (เก็บค่า ณ ตอนแลก เผื่อ required_score ของ reward เปลี่ยนภายหลัง)',
  `status` ENUM('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED') NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING=รอดำเนินการ (หัก stock+คะแนนไปแล้ว), APPROVED=อนุมัติ/มอบของแล้ว, REJECTED=แอดมินปฏิเสธ (ต้องคืน stock+คะแนนเสมอ), CANCELLED=พนักงาน/ระบบยกเลิกเอง (ต้องคืน stock+คะแนนเสมอ)',
  `redeem_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่กดแลก',
  PRIMARY KEY (`redeem_id`),
  INDEX `fk_reward_redeem_reward_idx` (`reward_id` ASC) VISIBLE,
  INDEX `idx_reward_redeem_employee` (`employee_id` ASC) VISIBLE,
  CONSTRAINT `fk_reward_redeem_employee`
    FOREIGN KEY (`employee_id`)
    REFERENCES `wellness_db`.`employee` (`employee_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_reward_redeem_reward`
    FOREIGN KEY (`reward_id`)
    REFERENCES `wellness_db`.`reward` (`reward_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE)
ENGINE = InnoDB
AUTO_INCREMENT = 25
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'ประวัติการแลกของรางวัลของพนักงาน';


-- -----------------------------------------------------
-- Table `wellness_db`.`score_transaction`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `wellness_db`.`score_transaction` (
  `transaction_id` INT NOT NULL AUTO_INCREMENT COMMENT 'รหัสรายการ (PK)',
  `submission_id` INT NULL DEFAULT NULL COMMENT 'อ้างอิง submission ที่ทำให้เกิดรายการนี้ (FK -> running_submission.submission_id) ใช้เมื่อ transaction_type = EARN',
  `redeem_id` INT NULL DEFAULT NULL COMMENT 'อ้างอิงการแลกของที่ทำให้เกิดรายการนี้ (FK -> reward_redeem.redeem_id) ใช้เมื่อ transaction_type = REDEEM หรือ ADJUST (คืนคะแนนตอน REJECTED/CANCELLED)',
  `employee_id` VARCHAR(20) NOT NULL COMMENT 'รหัสพนักงานเจ้าของรายการ',
  `score` INT NOT NULL COMMENT 'จำนวนคะแนน เป็นบวก=ได้คะแนนเพิ่ม, เป็นลบ=ถูกหักคะแนน (คะแนนคงเหลือของพนักงาน = SUM(score) ของทุกแถว)',
  `transaction_type` ENUM('EARN', 'REDEEM', 'ADJUST', 'EXPIRE') NOT NULL COMMENT 'EARN=ได้คะแนนจาก submission ที่อนุมัติ, REDEEM=ถูกหักตอนแลกของ (PENDING), ADJUST=ปรับคะแนนคืน/แก้ไขโดย admin (เช่น คืนคะแนนตอน redeem ถูก REJECTED), EXPIRE=คะแนนหมดอายุ',
  `remark` VARCHAR(255) NULL DEFAULT NULL COMMENT 'หมายเหตุ/เหตุผลของรายการ เช่น \"คืนคะแนนจากการยกเลิกแลกของ\"',
  `created_by` VARCHAR(20) NULL DEFAULT NULL COMMENT 'ผู้สร้างรายการ (NULL=ระบบสร้างอัตโนมัติ, มีค่า=admin เป็นคนทำรายการ)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'วันเวลาที่เกิดรายการ',
  PRIMARY KEY (`transaction_id`),
  INDEX `fk_score_transaction_running_submission_idx` (`submission_id` ASC) VISIBLE,
  INDEX `fk_score_transaction_reward_redeem_idx` (`redeem_id` ASC) VISIBLE,
  INDEX `idx_score_transaction_employee` (`employee_id` ASC) VISIBLE,
  CONSTRAINT `fk_score_transaction_employee`
    FOREIGN KEY (`employee_id`)
    REFERENCES `wellness_db`.`employee` (`employee_id`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_score_transaction_reward_redeem`
    FOREIGN KEY (`redeem_id`)
    REFERENCES `wellness_db`.`reward_redeem` (`redeem_id`)
    ON DELETE SET NULL
    ON UPDATE CASCADE,
  CONSTRAINT `fk_score_transaction_running_submission`
    FOREIGN KEY (`submission_id`)
    REFERENCES `wellness_db`.`running_submission` (`submission_id`)
    ON DELETE SET NULL
    ON UPDATE CASCADE)
ENGINE = InnoDB
AUTO_INCREMENT = 59
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_0900_ai_ci
COMMENT = 'Ledger บันทึกทุกรายการที่กระทบคะแนนพนักงาน ห้ามแก้ไข/ลบย้อนหลัง ให้ insert รายการปรับเข้าไปแทนเสมอ';


SET SQL_MODE=@OLD_SQL_MODE;
SET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS;
SET UNIQUE_CHECKS=@OLD_UNIQUE_CHECKS;